declare namespace SigApi {
    interface Station {
        /**
         * Returns the number of the station
         * 
         * @returns {number} The station number 
         */
        getNumber(): number
        /**
         * Returns the label of the Station in the current language
         * 
         * @returns {string} The label of the station of undefined if nothing is set
         */
        getLabel(): string
        /**
         * Returns the connection type of the station (SIG_CONST.STATION_STR_...)
         * 
         * @returns {string} The connection type of the station
         */
        getConType(): string
        /**
         * Returns the status of the station as number constant (SIG_CONST.STAT_STATION_...)
         * 
         * @returns {number} The stat of the station
         */
        getStatus(): number
        /**
         * Changes Station Parameters
         * 
         * @param {string|undefined} ipAddress ipAddress or undefined to keep current value
         * @param {number|undefined} port port or undefined to keep current value
         * @param {number|undefined} reconInterval reconInterval or undefined to keep current value
         * @returns {Promise} Promise -> resolve: ({stationNr: number, error: number}), reject: (stationNr: number, error: number, errortxt: string)
         * 
         * Possible values for parameter reconInterval:
         * * 1  .. 1 second (HIGH)
         * * 5  .. 5 seconds (MEDIUM)
         * * 10 .. 10 seconds (STANDARD)
         * * 30 .. 30 seconds (LOW)
         * * 0  .. do not reconnect
         * 
         * Possible error for reject:
         * * 0x0001 -> ERROR_UNKNOWN -> Unknown error: see errortext for details
         * * 0x0007 -> ERROR_COMMUNICATION -> no response from dataservice for this request -> check if the DS is running
         * * 0x0012 -> ERROR_INSUFFICIENT_PRIVILEGES -> not enough privileges -> check the access level of the current user
         * * 0x0039 -> ERROR_INVALID_STATION -> invalid station
         * * 0x0043 -> ERROR_INVALID_STATION_NUM -> unknown stationNr
         * * 0x0044 -> ERROR_INVALID_PARAMETER -> ipAddress, port or reconInterval invalid
         */
        changeStationParameters(ipAddress: string | undefined, port: number | undefined, reconInterval: number | undefined): Promise<{ stationNr: number, error: number }>
    }
}
